-- Generated by ant from your models, then edited: the generated version gave every
-- existing post the same empty slug, which the unique constraint refuses.

ALTER TABLE "posts" ADD COLUMN "slug" text;

UPDATE "posts" SET "slug" = trim(BOTH '-' FROM lower(regexp_replace("title", '[^a-zA-Z0-9]+', '-', 'g')));

ALTER TABLE "posts" ALTER COLUMN "slug" SET NOT NULL;

ALTER TABLE "posts" ADD CONSTRAINT "posts_slug_key" UNIQUE ("slug");
